# Class 1 (age 6-7): the world is good. Fairy tales and folk tales of India, letters born from pictures,
# the quality of numbers, form drawing, nature through the seasons. Everything is told, drawn and moved first.

FD_PRACTICE = [("Walk the form", "Walk today's form on the floor or in the courtyard, then 'draw' it in the air with the whole arm, then with one finger on the table."),
               ("Beanbag counting", "Toss a beanbag between you, counting 1 to 20 and back. Then count in a whisper and a loud voice, turn by turn."),
               ("Finger plays", "Do two finger rhymes, e.g. 'Ek do teen char, chalo chalo bazaar' with fingers walking.")]
LETTER_PRACTICE = [("Letter in the body", "Make today's letter with your bodies, then walk it on the floor, then trace it in a tray of sand or rangoli powder."),
                   ("Sound hunt", "Go around the house and find five things that begin with today's sound. Say each one slowly."),
                   ("Rhyme time", "Say a rhyme you know three times: loud, soft, and whispering. Clap the rhythm.")]
NUM_PRACTICE = [("Counting with things", "Count out tamarind seeds, rajma or pebbles: make groups of today's number all over the table."),
                ("Rhythmic counting", "Count 1–12 stepping forward, 12–1 stepping back. Clap on every 2nd, then every 3rd number."),
                ("Number hunt", "Find today's number in the house: how many legs on a chair, petals on a flower, wheels on the cycle?")]
NATURE_PRACTICE = [("Nature table", "Add something you found today to the nature table (a leaf, seed, stone or flower). Say its name together."),
                   ("Garden helper", "Water the plants or the tulsi pot together; notice one thing that changed since yesterday."),
                   ("Listening walk", "Sit outside for two minutes with eyes closed. Count how many different sounds you hear.")]

